# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /solr/admin/cores HTTP/1.1
Host: {{params(target)}}
Accept-Encoding: gzip
User-Agent: Mozilla/4.0 (compatible; MSIE 7.0; Windows NT 5.1; Trident/4.0; SE 2.X MetaSr 1.0; SE 2.X MetaSr 1.0; .NET CLR 2.0.50727; SE 2.X MetaSr 1.0)

`


    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(10),
    )
    rspIns, _ = poc.ParseBytesToHTTPResponse(rsp)
    reqIns, _ = poc.ParseBytesToHTTPRequest(req)
    if str.MatchAllOfRegexp(rsp,`<str name="name">([\s\S]*?)</str>([\s\S]*)<str name="instanceDir">`) {
            yakit.Info(
                "%v found 亿赛通电子文档安全管理系统远程代码执行漏洞", 
                addr, 
            )
            risk.NewRisk(
                addr,
                risk.title("亿赛通电子文档安全管理系统远程代码执行漏洞(CNVD-2021-26058)"),
                risk.severity("critical"),
                risk.titleVerbose("亿赛通电子文档安全管理系统远程代码执行漏洞(CNVD-2021-26058)"),
                risk.request(string(rspIns)),
                risk.response(string(reqIns)),
                risk.cve("CNVD-2021-26058"),
            )
        }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
